"""Registry of invoices by client."""

_ALL = []
_BY_KEY = None


def reset():
    """Forget every registered invoice."""
    global _BY_KEY
    del _ALL[:]
    _BY_KEY = None


def register(invoice):
    """Add one invoice to the registry."""
    _ALL.append(invoice)


def find(client):
    """Return the invoices registered under this client."""
    global _BY_KEY
    if _BY_KEY is None:
        _BY_KEY = {}
        for x in _ALL:
            _BY_KEY.setdefault(x.client, []).append(x)
    return _BY_KEY.get(client, [])

